# ==============================================================================# IOTEC MISSION CONTROL# 001_BOOT.py# ==============================================================================import osimport jsonimport platformimport socketimport datetimefrom pathlib import PathVERSION = "1.0.0"ROOT = Path(__file__).resolve().parentPASTAS = [    "MISSION_CONTROL",    "MISSION_CONTROL/assets",    "MISSION_CONTROL/assets/css",    "MISSION_CONTROL/assets/js",    "MISSION_CONTROL/assets/fonts",    "MISSION_CONTROL/assets/images",    "MISSION_CONTROL/assets/icons",    "MISSION_CONTROL/assets/sounds",    "MISSION_CONTROL/components",    "MISSION_CONTROL/config",    "MISSION_CONTROL/core",    "MISSION_CONTROL/database",    "MISSION_CONTROL/engines",    "MISSION_CONTROL/effects",    "MISSION_CONTROL/events",    "MISSION_CONTROL/logs",    "MISSION_CONTROL/maestro",    "MISSION_CONTROL/missions",    "MISSION_CONTROL/observability",    "MISSION_CONTROL/plugins",    "MISSION_CONTROL/radar",    "MISSION_CONTROL/security",    "MISSION_CONTROL/services",    "MISSION_CONTROL/styles",    "MISSION_CONTROL/scripts",    "MISSION_CONTROL/temp"]print("=" * 80)print("IOTEC MISSION CONTROL")print("BOOTSTRAP")print("=" * 80)for pasta in PASTAS:    caminho = ROOT / pasta    caminho.mkdir(parents=True, exist_ok=True)    print(f"[OK] {caminho}")config = {    "version": VERSION,    "created_at": datetime.datetime.now().isoformat(),    "hostname": socket.gethostname(),    "platform": platform.platform(),    "python": platform.python_version(),    "root": str(ROOT)}config_file = ROOT / "MISSION_CONTROL" / "config" / "system.json"with open(config_file, "w", encoding="utf-8") as f:    json.dump(config, f, indent=4, ensure_ascii=False)print()print("[OK] system.json criado")print()print("RESUMO")print("-" * 80)print(f"VersÃ£o.............: {VERSION}")print(f"Python.............: {platform.python_version()}")print(f"Sistema............: {platform.system()}")print(f"Computador.........: {socket.gethostname()}")print(f"DiretÃ³rio..........: {ROOT}")print("-" * 80)print("BOOT FINALIZADO")print("=" * 80)

